/// Shuffle · repeat · favourite with their state read here, so a favourite edit or a shuffle / repeat change
/// redraws this row only, not the whole full player. The favourite goes through `observedSong(id:)`: the library's
/// song lookup is not observed.
private struct PlayerToggles: View {
    let song: Song
    @Environment(AppEnvironment.self) private var env
    @Environment(PlaybackStore.self) private var playback
    @Environment(LibraryStore.self) private var library

    var body: some View {
        let isFavorite = library.observedSong(id: song.id)?.isFavorite ?? song.isFavorite
        PlayerToggleRow(isShuffleOn: playback.isShuffleEnabled, repeatMode: playback.repeatMode,
                        isFavorite: isFavorite,
                        onShuffle: { playback.setShuffleEnabled(!playback.isShuffleEnabled) },
                        onRepeat: { playback.setRepeatMode(NowPlayingView.nextRepeatMode(after: playback.repeatMode)) },
                        onFavorite: { env.libraryEditor.toggleFavorite(song.id) })
    }
}
```
`nextRepeatMode` is an internal static (:121), so it is reachable. Then drop `@Environment(LibraryStore.self) private var library` from NowPlayingView (line 28); it is used only at :100. Keep PlayerToggleRow's type and initialiser unchanged (seam rule).

